import numpy as np
from scipy.optimize import minimize

_ctx = {}

def project_capped(z, n):
    if z.shape != (n,) or not np.all(np.isfinite(z)):
        return None
    z = np.clip(z, -1e6, 1e6)
    s = n / 2.0
    lo, hi = np.min(z) - 1.0, np.max(z) + 1.0
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if np.sum(np.clip(z - mid, 0.0, 1.0)) > s:
            lo = mid
        else:
            hi = mid
    h = np.clip(z - 0.5 * (lo + hi), 0.0, 1.0)
    r = s - np.sum(h)
    for _ in range(n + 2):
        if abs(r) < 1e-14:
            break
        if r > 0:
            idx = np.argmax(1.0 - h)
            h[idx] = min(h[idx] + r, 1.0)
        else:
            idx = np.argmax(h)
            h[idx] = max(h[idx] + r, 0.0)
        r = s - np.sum(h)
    if not np.all(np.isfinite(h)) or np.any(h < -1e-12) or np.any(h > 1.0 + 1e-12):
        return None
    h = np.clip(h, 0.0, 1.0)
    if abs(np.sum(h) - s) > 1e-9:
        return None
    return h

def is_feasible(h, n):
    if h.shape != (n,) or not np.all(np.isfinite(h)):
        return False
    if np.any(h < -1e-12) or np.any(h > 1.0 + 1e-12):
        return False
    if abs(np.sum(h) - n / 2.0) > 1e-9:
        return False
    return True

def exact_score(h, n):
    if not is_feasible(h, n):
        return float('inf')
    c = np.correlate(h, 1.0 - h, mode='full')
    if not np.all(np.isfinite(c)):
        return float('inf')
    return float(np.max(c * (2.0 / n)))

def compute_lags(h, n):
    dx = 2.0 / n
    L = 2 * n - 1
    q = np.zeros(L)
    J = np.zeros((L, n))
    for d in range(-(n - 1), n):
        a = max(d, 0)
        b = max(-d, 0)
        m = n - abs(d)
        idx = d + n - 1
        ha = h[a:a + m]
        hb = h[b:b + m]
        q[idx] = dx * np.dot(ha, 1.0 - hb)
        J[idx, a:a + m] += dx * (1.0 - hb)
        J[idx, b:b + m] -= dx * ha
    return q, J

def _obj(z):
    return z[_ctx['n']]

def _obj_jac(z):
    n = _ctx['n']
    g = np.zeros(n + 1)
    g[n] = 1.0
    return g

def _ineq(z):
    n = _ctx['n']
    q, _ = compute_lags(z[:n], n)
    return z[n] - q

def _ineq_jac(z):
    n = _ctx['n']
    _, J = compute_lags(z[:n], n)
    L = 2 * n - 1
    A = np.zeros((L, n + 1))
    A[:, :n] = -J
    A[:, n] = 1.0
    return A

def _eq(z):
    n = _ctx['n']
    return np.array([np.sum(z[:n]) - n / 2.0])

def _eq_jac(z):
    n = _ctx['n']
    A = np.zeros((1, n + 1))
    A[0, :n] = 1.0
    return A

def solve_exact(x, n, maxiter):
    _ctx['n'] = n
    q0, _ = compute_lags(x, n)
    t0 = np.max(q0) + 1e-6
    z0 = np.empty(n + 1)
    z0[:n] = x
    z0[n] = t0
    bounds = [(0.0, 1.0)] * n + [(0.0, None)]
    constr = [
        {'type': 'ineq', 'fun': _ineq, 'jac': _ineq_jac},
        {'type': 'eq', 'fun': _eq, 'jac': _eq_jac},
    ]
    try:
        res = minimize(_obj, z0, jac=_obj_jac, method='SLSQP',
                       bounds=bounds, constraints=constr,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
    except Exception:
        return None
    if res.x is None or len(res.x) != n + 1:
        return None
    y = res.x[:n]
    if not np.all(np.isfinite(y)):
        return None
    y = project_capped(y, n)
    return y

def _try_add(pool, v, n):
    if v is None or v.shape != (n,) or not np.all(np.isfinite(v)):
        return
    if np.any(v < -1e-6) or np.any(v > 1.0 + 1e-6):
        return
    for s in pool:
        if np.max(np.abs(v - s)) < 1e-8:
            return
    pool.append(v.copy())

def build_starts(fallback, n, rng, count):
    pool = []
    _try_add(pool, fallback, n)
    _try_add(pool, project_capped(fallback[::-1].copy(), n), n)
    _try_add(pool, project_capped(1.0 - fallback, n), n)
    _try_add(pool, project_capped((1.0 - fallback)[::-1].copy(), n), n)
    _try_add(pool, np.full(n, 0.5), n)
    blk = np.zeros(n)
    blk[:n // 2] = 1.0
    if n % 2:
        blk[n // 2] = 0.5
    _try_add(pool, project_capped(blk, n), n)
    alt = np.where(np.arange(n) % 2 == 0, 1.0, 0.0)
    if n % 2:
        alt[n // 2] = 0.5
    _try_add(pool, project_capped(alt, n), n)
    _try_add(pool, project_capped(fallback + rng.normal(0, 0.05, n), n), n)
    _try_add(pool, project_capped(fallback + rng.normal(0, 0.18, n), n), n)
    _try_add(pool, project_capped(rng.uniform(0, 1, n), n), n)
    P = max(2, n // 3)
    i = np.arange(n)
    cos_v = 0.5 + 0.45 * np.cos(2.0 * np.pi * i / P)
    _try_add(pool, project_capped(cos_v, n), n)
    cos_v2 = 0.5 + 0.45 * np.cos(2.0 * np.pi * i / max(2, n // 2 + 1))
    _try_add(pool, project_capped(cos_v2, n), n)
    return pool[:count]

def coord_refine(h, n, n_passes):
    h = h.copy()
    best_s = float(exact_score(h, n))
    deltas = [0.002, 0.005, 0.01, 0.02, -0.002, -0.005, -0.01, -0.02]
    for _ in range(n_passes):
        improved = False
        for i in range(n):
            for delta in deltas:
                h2 = h.copy()
                h2[i] = h[i] + delta
                h2 = project_capped(h2, n)
                if h2 is None:
                    continue
                s2 = float(exact_score(h2, n))
                if s2 < best_s - 1e-14:
                    h, best_s, improved = h2, s2, True
                    break
        if not improved:
            break
    return h, best_s

